style.css:
/* Hide the default YouTube logo */
ytd-topbar-logo-renderer svg {
  display: none !important;
}

/* Regular sized Shadow + Sonic GIF */
ytd-topbar-logo-renderer {
  width: 56px !important;
  height: 56px !important;

  background-image: url("https://media.tenor.com/aYCL8tBRETgAAAAi/shadow-sonic.gif");
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;

  image-rendering: pixelated;
  transition: transform 0.2s ease;
}

/* Bounce effect on hover */
ytd-topbar-logo-renderer:hover {
  animation: shadowBounce 0.4s infinite alternate;
}

@keyframes shadowBounce {
  from { transform: translateY(0); }
  to   { transform: translateY(-5px); }
}
